@startuml

class Kinepolis {}

class Cinema {
  + town : string
}

class Theatre {
  + capacity : int
}

class Movie {
  + title : string
}

class MovieCopy {
}

class Show {
  + startTime : datetime
  + isPublished : boolean
}

class Reservation {
  + reservationTime : datetime
}

class SeatReservation extends Reservation {
  + seatNumber : string
  + isCancelled : boolean
}

class Ticket {
  + seatNumber : string
}

class CreditCard {
  + cardNumber : string
}

class Offer {
  + expiryDate : datetime
}

class FreeTicket {
}

Kinepolis "1" *-- "*" Cinema
Cinema "1" *-- "*" Theatre
Cinema "1" *-- "*" MovieCopy
Theatre "1" *-- "*" Show
Movie "1" -- "*" MovieCopy
Show "1" -- "1" MovieCopy
Show "1" -- "*" SeatReservation
Show "1" -- "*" Ticket
Reservation "*" -- "1" CreditCard
SeatReservation "*" -- "0..1" Offer
Offer "0..1" -- "1" SeatReservation
FreeTicket "1" -- "1" SeatReservation

@enduml

